// CBSE 12 Mathematics ch05 Continuity and Differentiability — practice bank with independent re-solve
// checks: every derivative key is compared with a central-difference derivative of the original function
// at sample points; continuity constants with one-sided limits evaluated numerically; implicit slopes with
// -F_x/F_y from numeric partials; parametric slopes after eliminating the parameter (or Newton inversion).
// Rolle's and Lagrange's mean value theorems are deleted (2026-27) and appear nowhere.
import { Q, caseQ, child, mk, r, solve2 } from '../../cbse-12-mathematics-ch01/src/lib.mjs';

// ---------------------------------------------------------------- numeric calculus helpers
export const D = (g, x, h = 1e-5) => (g(x + h) - g(x - h)) / (2 * h);
export const D2 = (g, x, h = 1e-4) => (g(x + h) - 2 * g(x) + g(x - h)) / (h * h);
export const close = (a, b, tol = 1e-5) => Math.abs(a - b) <= tol * Math.max(1, Math.abs(b));
/** dg is the derivative of g at every sample point (numerically). */
export const sameD = (g, dg, xs) => xs.every((x) => close(D(g, x), dg(x)));
export const sameD2 = (g, d2g, xs) => xs.every((x) => close(D2(g, x), d2g(x), 1e-4));
/** One-sided limit by evaluating very close to a (side -1 left, +1 right). */
export const lim = (g, a, side) => g(a + side * 1e-8);
export const LHD = (g, a, h = 1e-7) => (g(a) - g(a - h)) / h;
export const RHD = (g, a, h = 1e-7) => (g(a + h) - g(a)) / h;
/** Slope of F(x, y) = 0 at (x, y) from numeric partial derivatives: -F_x / F_y. */
export const islope = (F, x, y, h = 1e-6) => -((F(x + h, y) - F(x - h, y)) / (F(x, y + h) - F(x, y - h)));
const pickD = (g, opts, xs) => opts.map(([, dg]) => sameD(g, dg, xs));
const L = Math.log, E = Math.exp, S = Math.sin, Co = Math.cos, T = Math.tan, sq = Math.sqrt;
const isCont = (g, a, fa) => close(lim(g, a, -1), fa) && close(lim(g, a, 1), fa);

// =============================================================== MCQ
Q('m01', mk.mcq({ stem: r`A real function $f$ is continuous at a point $c$ of its domain when`, opts: [r`$f(c)$ is defined`, r`$\lim_{x \to c} f(x)$ exists`, r`$\lim_{x \to c} f(x) = f(c)$`, r`$f(c) = 0$`], key: 'c', sol: r`Continuity needs the limit to exist **and** equal the value of the function. Being defined, or having a limit, is not enough on its own.`, d: 1, c: 'recall', t: [1], time: 30 }), (C) => C.key('c'));

Q('m02', mk.mcq({ stem: r`The value of $k$ for which $f(x) = \begin{cases} kx - 3, & x \le 2 \\ x^2 + 1, & x > 2 \end{cases}$ is continuous at $x = 2$ is`, opts: ['$4$', '$3$', '$1$', '$5$'], key: 'a', sol: r`Left-hand limit and value: $2k - 3$. Right-hand limit: $4 + 1 = 5$. So $2k - 3 = 5$, $k = 4$.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => C.which([4, 3, 1, 5].map((k) => isCont((x) => (x <= 2 ? k * x - 3 : x * x + 1), 2, 2 * k - 3)), true));

Q('m03', mk.mcq({ stem: r`If $[x]$ denotes the greatest integer less than or equal to $x$, the number of points in the open interval $(0, 3)$ at which $f(x) = [x]$ is discontinuous is`, opts: ['$0$', '$1$', '$2$', '$3$'], key: 'c', sol: r`$[x]$ jumps by $1$ at every integer and is constant between integers. Inside $(0, 3)$ the integers are $1$ and $2$: two points.`, d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { let n = 0; for (let k = 1; k < 300; k++) { const a = k / 100; if (Math.floor(a - 1e-9) !== Math.floor(a + 1e-9)) n++; } C.which([0, 1, 2, 3], n); });

Q('m04', mk.mcq({ stem: r`Which of the following functions is continuous at $x = 0$?`, opts: [r`$f(x) = \dfrac{1}{x}$ for $x \ne 0$, $f(0) = 0$`, r`$f(x) = |x|$`, r`$f(x) = \dfrac{\sin x}{x}$ for $x \ne 0$, $f(0) = 0$`, r`$f(x) = \dfrac{|x|}{x}$ for $x \ne 0$, $f(0) = 1$`], key: 'b', sol: r`$|x| \to 0 = |0|$ from both sides. The reciprocal grows without bound; $\dfrac{\sin x}{x} \to 1 \ne 0$; $\dfrac{|x|}{x}$ is $-1$ on the left and $1$ on the right.`, d: 3, c: 'analysis', t: [1], time: 75 }), (C) => C.which([[(x) => 1 / x, 0], [Math.abs, 0], [(x) => S(x) / x, 0], [(x) => Math.abs(x) / x, 1]].map(([g, v]) => isCont(g, 0, v)), true));

Q('m05', mk.mcq({ stem: 'Which statement is always true for a real function at a point $c$?', opts: ['If it is continuous at $c$, it is differentiable at $c$.', 'If it is differentiable at $c$, it is continuous at $c$.', 'If it is not differentiable at $c$, it is not continuous at $c$.', 'If its graph has a corner at $c$, it is not continuous at $c$.'], key: 'b', sol: r`Differentiability forces continuity. The converse fails: $|x|$ is continuous at $0$ but has a corner there, so it is not differentiable.`, d: 1, c: 'recall', t: [2], time: 45 }), (C) => { C.assert(isCont(Math.abs, 0, 0) && !close(LHD(Math.abs, 0), RHD(Math.abs, 0)), '|x| continuous, not differentiable at 0'); C.key('b'); });

Q('m06', mk.mcq({ stem: r`At $x = 3$, the function $f(x) = |x - 3|$ is`, opts: ['continuous and differentiable', 'continuous but not differentiable', 'differentiable but not continuous', 'neither continuous nor differentiable'], key: 'b', sol: r`Both one-sided limits are $0 = f(3)$, so $f$ is continuous. Left-hand derivative $-1$, right-hand derivative $1$: unequal, so not differentiable.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => { const g = (x) => Math.abs(x - 3); C.assert(isCont(g, 3, 0) && close(LHD(g, 3), -1) && close(RHD(g, 3), 1), 'LHD -1, RHD 1'); C.key('b'); });

const o07 = [[r`$\cos(x^3)$`, (x) => Co(x ** 3)], [r`$3x^2\cos(x^3)$`, (x) => 3 * x * x * Co(x ** 3)], [r`$3x^2\sin(x^3)$`, (x) => 3 * x * x * S(x ** 3)], [r`$-3x^2\cos(x^3)$`, (x) => -3 * x * x * Co(x ** 3)]];
Q('m07', mk.mcq({ stem: r`$\dfrac{d}{dx}\left[\sin(x^3)\right]$ equals`, opts: o07.map((o) => o[0]), key: 'b', sol: r`Chain rule: derivative of the outer sine at $x^3$, times the derivative of $x^3$: $\cos(x^3) \cdot 3x^2$.`, d: 2, c: 'understanding', t: [2], time: 45 }), (C) => C.which(pickD((x) => S(x ** 3), o07, [0.4, 0.9, 1.3]), true));

const o08 = [[r`$\dfrac{4x}{\sqrt{1 + 4x^2}}$`, (x) => (4 * x) / sq(1 + 4 * x * x)], [r`$\dfrac{8x}{\sqrt{1 + 4x^2}}$`, (x) => (8 * x) / sq(1 + 4 * x * x)], [r`$\dfrac{1}{2\sqrt{1 + 4x^2}}$`, (x) => 1 / (2 * sq(1 + 4 * x * x))], [r`$\dfrac{2x}{\sqrt{1 + 4x^2}}$`, (x) => (2 * x) / sq(1 + 4 * x * x)]];
Q('m08', mk.mcq({ stem: r`The derivative of $\sqrt{1 + 4x^2}$ with respect to $x$ is`, opts: o08.map((o) => o[0]), key: 'a', sol: r`$\dfrac{1}{2\sqrt{1 + 4x^2}} \cdot 8x = \dfrac{4x}{\sqrt{1 + 4x^2}}$. Forgetting the factor $\dfrac12$ gives the $8x$ option.`, d: 2, c: 'understanding', t: [2], time: 60 }), (C) => C.which(pickD((x) => sq(1 + 4 * x * x), o08, [0.3, 1, 2]), true));

const o09 = [[r`$\dfrac{1}{1 + 4x^2}$`, (x) => 1 / (1 + 4 * x * x)], [r`$\dfrac{2}{1 + 4x^2}$`, (x) => 2 / (1 + 4 * x * x)], [r`$\dfrac{2}{1 + 2x^2}$`, (x) => 2 / (1 + 2 * x * x)], [r`$\dfrac{2}{\sqrt{1 - 4x^2}}$`, (x) => 2 / sq(1 - 4 * x * x)]];
Q('m09', mk.mcq({ stem: r`$\dfrac{d}{dx}\left[\tan^{-1}(2x)\right]$ equals`, opts: o09.map((o) => o[0]), key: 'b', sol: r`$\dfrac{1}{1 + (2x)^2} \cdot 2 = \dfrac{2}{1 + 4x^2}$. The square-root form belongs to the inverse sine.`, d: 2, c: 'understanding', t: [3], time: 45 }), (C) => C.which(pickD((x) => Math.atan(2 * x), o09, [0.1, 0.3, 0.45]), true));

Q('m10', mk.mcq({ stem: r`If $x^2 + y^2 = 169$, then $\dfrac{dy}{dx}$ at the point $(5, 12)$ is`, opts: [r`$-\dfrac{5}{12}$`, r`$\dfrac{5}{12}$`, r`$-\dfrac{12}{5}$`, r`$\dfrac{12}{5}$`], key: 'a', sol: r`Differentiate implicitly: $2x + 2y\dfrac{dy}{dx} = 0$, so $\dfrac{dy}{dx} = -\dfrac{x}{y} = -\dfrac{5}{12}$.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => { const s = D((x) => sq(169 - x * x), 5); C.which([-5 / 12, 5 / 12, -12 / 5, 12 / 5].map((v) => close(v, s)), true); });

Q('m11', mk.mcq({ stem: r`If $x^2 + xy + y^2 = 7$, then $\dfrac{dy}{dx}$ at $(1, 2)$ is`, opts: [r`$-\dfrac{4}{5}$`, r`$-\dfrac{5}{4}$`, r`$\dfrac{4}{5}$`, '$-1$'], key: 'a', sol: r`$2x + y + x\dfrac{dy}{dx} + 2y\dfrac{dy}{dx} = 0$ gives $\dfrac{dy}{dx} = -\dfrac{2x + y}{x + 2y} = -\dfrac{4}{5}$ at $(1, 2)$. Forgetting the product rule on $xy$ is the usual slip.`, d: 3, c: 'application', t: [3], time: 90 }), (C) => { const y = (x) => (-x + sq(28 - 3 * x * x)) / 2; C.assert(close(y(1), 2), 'point on curve'); const s = D(y, 1); C.which([-4 / 5, -5 / 4, 4 / 5, -1].map((v) => close(v, s)), true); });

const o12 = [[r`$e^{\sin x}$`, (x) => E(S(x))], [r`$\cos x \, e^{\sin x}$`, (x) => Co(x) * E(S(x))], [r`$e^{\cos x}$`, (x) => E(Co(x))], [r`$\sin x \, e^{\sin x - 1}$`, (x) => S(x) * E(S(x) - 1)]];
Q('m12', mk.mcq({ stem: r`$\dfrac{d}{dx}\left(e^{\sin x}\right)$ equals`, opts: o12.map((o) => o[0]), key: 'b', sol: r`The exponential keeps its form; multiply by the derivative of the exponent, $\cos x$. The power rule does not apply to $e^{u}$.`, d: 2, c: 'understanding', t: [4], time: 45 }), (C) => C.which(pickD((x) => E(S(x)), o12, [0.2, 1, 2.5]), true));

const o13 = [[r`$\dfrac{1}{x^2 + 5}$`, (x) => 1 / (x * x + 5)], [r`$\dfrac{2x}{x^2 + 5}$`, (x) => (2 * x) / (x * x + 5)], [r`$\dfrac{2x}{\log(x^2 + 5)}$`, (x) => (2 * x) / L(x * x + 5)], [r`$2x\log(x^2 + 5)$`, (x) => 2 * x * L(x * x + 5)]];
Q('m13', mk.mcq({ stem: r`Here $\log$ is the natural logarithm. $\dfrac{d}{dx}\left[\log(x^2 + 5)\right]$ equals`, opts: o13.map((o) => o[0]), key: 'b', sol: r`$\dfrac{1}{x^2 + 5} \cdot 2x$: derivative of the inside over the inside.`, d: 2, c: 'understanding', t: [4], time: 45 }), (C) => C.which(pickD((x) => L(x * x + 5), o13, [0.5, 1, 3]), true));

Q('m14', mk.mcq({ stem: r`If $y = x^x$ ($x > 0$), then $\dfrac{dy}{dx}$ at $x = 2$ is`, opts: ['$4$', r`$4(1 + \log 2)$`, r`$2(1 + \log 2)$`, r`$4\log 2$`], key: 'b', sol: r`$\log y = x\log x$, so $\dfrac{1}{y}\dfrac{dy}{dx} = \log x + 1$ and $\dfrac{dy}{dx} = x^x(1 + \log x)$. At $x = 2$: $4(1 + \log 2)$.`, d: 3, c: 'application', t: [4], time: 90 }), (C) => { const s = D((x) => x ** x, 2); C.which([4, 4 * (1 + L(2)), 2 * (1 + L(2)), 4 * L(2)].map((v) => close(v, s)), true); });

Q('m15', mk.mcq({ stem: r`If $x = 3t^2$ and $y = 6t$ ($t > 0$), then $\dfrac{dy}{dx}$ equals`, opts: ['$t$', r`$\dfrac{1}{t}$`, '$2t$', r`$\dfrac{6}{t}$`], key: 'b', sol: r`$\dfrac{dy}{dt} = 6$, $\dfrac{dx}{dt} = 6t$, so $\dfrac{dy}{dx} = \dfrac{6}{6t} = \dfrac{1}{t}$.`, d: 2, c: 'understanding', t: [5], time: 45 }), (C) => { const t = 1.5; const s = D((x) => 6 * sq(x / 3), 3 * t * t); C.which([t, 1 / t, 2 * t, 6 / t].map((v) => close(v, s)), true); });

const o16 = [[r`$2e^{2x}$`, (x) => 2 * E(2 * x)], [r`$4e^{2x}$`, (x) => 4 * E(2 * x)], [r`$e^{2x}$`, (x) => E(2 * x)], [r`$4xe^{2x}$`, (x) => 4 * x * E(2 * x)]];
Q('m16', mk.mcq({ stem: r`If $y = e^{2x}$, then $\dfrac{d^2y}{dx^2}$ equals`, opts: o16.map((o) => o[0]), key: 'b', sol: r`$\dfrac{dy}{dx} = 2e^{2x}$ and differentiating again gives $4e^{2x}$. The first option is only the first derivative.`, d: 2, c: 'understanding', t: [5], time: 45 }), (C) => C.which(o16.map(([, g2]) => sameD2((x) => E(2 * x), g2, [0, 0.5, 1])), true));

Q('m17', mk.mcq({ stem: r`If $y = 5\sin 3x$, then $\dfrac{d^2y}{dx^2} + ky = 0$ for every $x$ when $k$ equals`, opts: ['$3$', '$9$', '$-9$', '$25$'], key: 'b', sol: r`$y' = 15\cos 3x$, $y'' = -45\sin 3x = -9y$. So $y'' + 9y = 0$.`, d: 3, c: 'application', t: [5], time: 75 }), (C) => { const y = (x) => 5 * S(3 * x); C.which([3, 9, -9, 25].map((k) => [0.3, 0.7, 1.1].every((x) => Math.abs(D2(y, x) + k * y(x)) < 1e-3)), true); });

const o18 = [[r`$\dfrac{1}{\sqrt{1 - x^4}}$`, (x) => 1 / sq(1 - x ** 4)], [r`$\dfrac{2x}{\sqrt{1 - x^4}}$`, (x) => (2 * x) / sq(1 - x ** 4)], [r`$\dfrac{2x}{\sqrt{1 - x^2}}$`, (x) => (2 * x) / sq(1 - x * x)], [r`$-\dfrac{2x}{\sqrt{1 - x^4}}$`, (x) => (-2 * x) / sq(1 - x ** 4)]];
Q('m18', mk.mcq({ stem: r`For $0 < x < 1$, $\dfrac{d}{dx}\left[\sin^{-1}(x^2)\right]$ equals`, opts: o18.map((o) => o[0]), key: 'b', sol: r`$\dfrac{1}{\sqrt{1 - (x^2)^2}} \cdot 2x = \dfrac{2x}{\sqrt{1 - x^4}}$. The minus sign belongs to the inverse cosine.`, d: 2, c: 'understanding', t: [3], time: 60 }), (C) => C.which(pickD((x) => Math.asin(x * x), o18, [0.2, 0.5, 0.8]), true));

// =============================================================== assertion-reason
Q('ar1', mk.ar({ a: r`The function $f(x) = |x|$ is continuous at $x = 0$.`, r: r`The function $f(x) = |x|$ is differentiable at $x = 0$.`, key: 'c', sol: r`Both one-sided limits of $|x|$ at $0$ are $0 = f(0)$, so A is true. The one-sided derivatives are $-1$ and $1$, so R is false.`, d: 2, c: 'analysis', t: [1, 2] }), (C) => { C.assert(isCont(Math.abs, 0, 0) && !close(LHD(Math.abs, 0), RHD(Math.abs, 0)), 'A true, R false'); C.key('c'); });

Q('ar2', mk.ar({ a: r`If $f$ is differentiable at $x = c$, then $f$ is continuous at $x = c$.`, r: r`$\lim_{h \to 0}\left[f(c + h) - f(c)\right] = \lim_{h \to 0}\dfrac{f(c + h) - f(c)}{h} \cdot h = f'(c) \cdot 0 = 0$.`, key: 'a', sol: r`R is exactly the proof of A: the difference $f(c + h) - f(c)$ tends to $0$, so $f(c + h) \to f(c)$. Both true; R explains A.`, d: 3, c: 'analysis', t: [2] }), (C) => { const g = (x) => x ** 3 + 2 * x; C.assert(Math.abs(g(1 + 1e-7) - g(1)) < 1e-5, 'difference tends to 0 for a sample differentiable function'); C.key('a'); });

Q('ar3', mk.ar({ a: r`$\dfrac{d}{dx}(\log x) = \dfrac{1}{x}$ for $x > 0$.`, r: r`$\log x$ is not defined for $x \le 0$.`, key: 'b', sol: r`Both statements are true. R only describes the domain; it does not explain why the derivative is $\dfrac{1}{x}$.`, d: 2, c: 'analysis', t: [4] }), (C) => { C.assert(sameD(L, (x) => 1 / x, [0.5, 2, 7]), 'derivative 1/x'); C.key('b'); });

Q('ar4', mk.ar({ a: r`For $y = x^x$ ($x > 0$), $\dfrac{dy}{dx} = x \cdot x^{x - 1} = x^x$.`, r: r`The rule $\dfrac{d}{dx}(x^n) = nx^{n - 1}$ holds only when the exponent $n$ is a constant.`, key: 'd', sol: r`The exponent of $x^x$ is the variable itself, so the power rule cannot be used; logarithmic differentiation gives $x^x(1 + \log x)$. A is false and R is true.`, d: 3, c: 'analysis', t: [4] }), (C) => { C.assert(!close(D((x) => x ** x, 2), 4) && close(D((x) => x ** x, 2), 4 * (1 + L(2))), 'x^x derivative is not x^x'); C.key('d'); });

Q('ar5', mk.ar({ a: r`If $y = \sin x$, then $\dfrac{d^2y}{dx^2} + y = 0$.`, r: r`The second derivative of $\sin x$ is $-\sin x$.`, key: 'a', sol: r`By R, $y'' = -\sin x = -y$, which rearranges to A. Both true; R explains A.`, d: 2, c: 'understanding', t: [5] }), (C) => { C.assert([0.3, 1.2, 2].every((x) => Math.abs(D2(S, x) + S(x)) < 1e-4), "y'' + y = 0"); C.key('a'); });

Q('ar6', mk.ar({ a: r`The greatest integer function $f(x) = [x]$ is continuous at $x = 2$.`, r: r`At every integer, the left-hand and right-hand limits of $[x]$ are unequal.`, key: 'd', sol: r`At $x = 2$ the left-hand limit is $1$ and the right-hand limit is $2$, so $[x]$ is not continuous there: A is false. R is true for every integer.`, d: 2, c: 'analysis', t: [1] }), (C) => { C.assert(lim(Math.floor, 2, -1) === 1 && lim(Math.floor, 2, 1) === 2, 'limits 1 and 2'); C.key('d'); });

// =============================================================== true-false
Q('tf1', mk.tf({ stem: 'A polynomial function is continuous at every real number.', key: 't', sol: r`Constants and $x$ are continuous, and sums and products of continuous functions are continuous, so every polynomial is continuous on $\mathbb{R}$.`, d: 1, c: 'recall', t: [1] }), (C) => { const p = (x) => 2 * x ** 3 - x + 4; C.assert([-2, 0, 1.5].every((a) => isCont(p, a, p(a))), 'sample polynomial continuous'); C.key('t'); });
Q('tf2', mk.tf({ stem: r`The function $f(x) = |x + 1|$ is differentiable at $x = -1$.`, key: 'f', sol: r`At $x = -1$ the left-hand derivative is $-1$ and the right-hand derivative is $1$; the graph has a corner. False.`, d: 2, c: 'understanding', t: [2] }), (C) => { const g = (x) => Math.abs(x + 1); C.assert(close(LHD(g, -1), -1) && close(RHD(g, -1), 1), 'corner'); C.key('f'); });
Q('tf3', mk.tf({ stem: r`$\dfrac{d}{dx}\left(\cos^{-1} x\right) = \dfrac{1}{\sqrt{1 - x^2}}$ for $-1 < x < 1$.`, key: 'f', sol: r`The correct derivative has a minus sign: $-\dfrac{1}{\sqrt{1 - x^2}}$. Inverse cosine is a decreasing function. False.`, d: 2, c: 'understanding', t: [3] }), (C) => { C.assert(sameD(Math.acos, (x) => -1 / sq(1 - x * x), [-0.5, 0, 0.6]), 'negative'); C.key('f'); });
Q('tf4', mk.tf({ stem: r`$\dfrac{d}{dx}(\log 5) = \dfrac{1}{5}$.`, key: 'f', sol: r`$\log 5$ is a constant, so its derivative is $0$. The rule $\dfrac{1}{x}$ applies to $\log x$, not to the log of a fixed number. False.`, d: 1, c: 'understanding', t: [4] }), (C) => { C.assert(D(() => L(5), 1) === 0, 'constant'); C.key('f'); });
Q('tf5', mk.tf({ stem: r`If $x = t^3$ and $y = t^2$ ($t \ne 0$), then $\dfrac{dy}{dx} = \dfrac{2}{3t}$.`, key: 't', sol: r`$\dfrac{dy}{dt} = 2t$ and $\dfrac{dx}{dt} = 3t^2$, so the ratio is $\dfrac{2t}{3t^2} = \dfrac{2}{3t}$. True.`, d: 2, c: 'understanding', t: [5] }), (C) => { const t = 1.3; C.assert(close(D((x) => Math.cbrt(x) ** 2, t ** 3), 2 / (3 * t)), 'eliminated'); C.key('t'); });

// =============================================================== fill in the blank
Q('fb1', mk.fill({ stem: r`If $f(x) = \begin{cases} 3x + k, & x < 1 \\ 7, & x = 1 \\ 5x + 2, & x > 1 \end{cases}$ is continuous at $x = 1$, then $k =$ ___.`, acc: [['4', '$4$']], sol: r`Right-hand limit $5 + 2 = 7 = f(1)$; the left-hand limit $3 + k$ must also be $7$, so $k = 4$.`, d: 2, c: 'understanding', t: [1] }), (C) => { const k = 7 - 3; const g = (x) => (x < 1 ? 3 * x + k : x === 1 ? 7 : 5 * x + 2); C.assert(isCont(g, 1, 7), 'continuous'); C.blank(k); });
Q('fb2', mk.fill({ stem: r`If $f(x) = (2x + 1)^5$, then $f'(0) =$ ___.`, acc: [['10', '$10$']], sol: r`$f'(x) = 5(2x + 1)^4 \cdot 2 = 10(2x + 1)^4$, and at $x = 0$ this is $10$.`, d: 2, c: 'understanding', t: [2] }), (C) => C.blank(Math.round(D((x) => (2 * x + 1) ** 5, 0) * 1e6) / 1e6));
Q('fb3', mk.fill({ stem: r`The value of $\dfrac{d}{dx}\left(\tan^{-1} x\right)$ at $x = 1$ is ___.`, acc: [['1/2', '0.5', r`$\dfrac{1}{2}$`]], sol: r`$\dfrac{1}{1 + x^2}$ at $x = 1$ is $\dfrac{1}{2}$.`, d: 1, c: 'recall', t: [3] }), (C) => C.blank(Math.round(D(Math.atan, 1) * 1e6) / 1e6));
Q('fb4', mk.fill({ stem: r`If $y = \log(x^2 + 3x + 1)$, then the value of $\dfrac{dy}{dx}$ at $x = 0$ is ___.`, acc: [['3', '$3$']], sol: r`$\dfrac{dy}{dx} = \dfrac{2x + 3}{x^2 + 3x + 1}$; at $x = 0$ it is $\dfrac{3}{1} = 3$.`, d: 2, c: 'understanding', t: [4] }), (C) => C.blank(Math.round(D((x) => L(x * x + 3 * x + 1), 0) * 1e6) / 1e6));
Q('fb5', mk.fill({ stem: r`If $x = 2t + 1$ and $y = t^2 - 4$, then $\dfrac{dy}{dx}$ at $t = 3$ is ___.`, acc: [['3', '$3$']], sol: r`$\dfrac{dy}{dx} = \dfrac{2t}{2} = t$, so at $t = 3$ it is $3$.`, d: 2, c: 'understanding', t: [5] }), (C) => C.blank(Math.round(D((x) => ((x - 1) / 2) ** 2 - 4, 7) * 1e6) / 1e6));

// =============================================================== numerical
Q('n01', mk.num({ stem: r`Find the value of $k$ for which $f(x) = \begin{cases} \dfrac{x^2 - 9}{x - 3}, & x \ne 3 \\ k, & x = 3 \end{cases}$ is continuous at $x = 3$.`, value: 6, sol: r`For $x \ne 3$, $\dfrac{x^2 - 9}{x - 3} = x + 3 \to 6$. So $k = 6$.`, scheme: [['Limit $6$ and $k = 6$', 1]], d: 2, c: 'understanding', t: [1], time: 60 }), (C) => { const g = (x) => (x * x - 9) / (x - 3); C.assert(close(lim(g, 3, -1), lim(g, 3, 1)), 'limit exists'); C.val(lim(g, 3, 1), 1e-5); });
Q('n02', mk.num({ stem: r`Find $k$ so that $f(x) = \begin{cases} \dfrac{1 - \cos 4x}{x^2}, & x \ne 0 \\ k, & x = 0 \end{cases}$ is continuous at $x = 0$.`, value: 8, sol: r`$1 - \cos 4x = 2\sin^2 2x$, so $\dfrac{1 - \cos 4x}{x^2} = 8\left(\dfrac{\sin 2x}{2x}\right)^2 \to 8$. Hence $k = 8$.`, scheme: [['Rewrite with $\\sin 2x$', 0.5], ['$k = 8$', 0.5]], d: 3, c: 'application', t: [1], time: 120 }), (C) => { const g = (x) => (1 - Co(4 * x)) / (x * x); C.assert(Math.abs(g(1e-3) - 8) < 1e-3 && Math.abs(g(-1e-3) - 8) < 1e-3, 'limit 8'); C.val(8); });
Q('n03', mk.num({ stem: r`If $f(x) = (3x^2 - 1)^4$, find $f'(1)$.`, value: 192, sol: r`$f'(x) = 4(3x^2 - 1)^3 \cdot 6x$. At $x = 1$: $4 \times 8 \times 6 = 192$.`, scheme: [['Chain rule', 0.5], ['$192$', 0.5]], d: 2, c: 'understanding', t: [2], time: 60 }), (C) => C.val(D((x) => (3 * x * x - 1) ** 4, 1), 1e-3));
Q('n04', mk.num({ stem: r`If $y = \tan^{-1}(x^2)$, find the value of $\dfrac{dy}{dx}$ at $x = 1$.`, value: 1, sol: r`$\dfrac{dy}{dx} = \dfrac{2x}{1 + x^4}$, which is $\dfrac{2}{2} = 1$ at $x = 1$.`, scheme: [['$\\dfrac{2x}{1 + x^4}$ and value $1$', 1]], d: 2, c: 'understanding', t: [3], time: 60 }), (C) => C.val(D((x) => Math.atan(x * x), 1), 1e-6));
Q('n05', mk.num({ stem: r`If $y = x^{\sin x}$ ($x > 0$), find $\dfrac{dy}{dx}$ at $x = \dfrac{\pi}{2}$.`, value: 1, sol: r`$\log y = \sin x \log x$, so $\dfrac{dy}{dx} = x^{\sin x}\left(\cos x\log x + \dfrac{\sin x}{x}\right)$. At $x = \dfrac{\pi}{2}$: $\dfrac{\pi}{2}\left(0 + \dfrac{2}{\pi}\right) = 1$.`, scheme: [['Log differentiation', 0.5], ['Value $1$', 0.5]], d: 4, c: 'application', t: [4], time: 150 }), (C) => C.val(D((x) => x ** S(x), Math.PI / 2), 1e-6));
Q('n06', mk.num({ stem: r`If $y = e^{2x} + \log x$, find $\dfrac{dy}{dx}$ at $x = 1$, correct to two decimal places.`, value: 15.78, tol: 0.01, sol: r`$\dfrac{dy}{dx} = 2e^{2x} + \dfrac{1}{x}$; at $x = 1$, $\dfrac{dy}{dx} = 2e^2 + 1 = 15.78$ to two decimal places.`, scheme: [['$2e^{2x} + \\dfrac{1}{x}$, then $15.78$', 1]], d: 2, c: 'understanding', t: [4], time: 75 }), (C) => C.val(D((x) => E(2 * x) + L(x), 1), 0.01));
Q('n07', mk.num({ stem: r`For $y = x^3 - 6x^2 + 5$, find the value of $x$ at which $\dfrac{d^2y}{dx^2} = 0$.`, value: 2, sol: r`$y' = 3x^2 - 12x$, $y'' = 6x - 12 = 0$ at $x = 2$.`, scheme: [['$y\'\' = 6x - 12$, $x = 2$', 1]], d: 2, c: 'understanding', t: [5], time: 60 }), (C) => { const y = (x) => x ** 3 - 6 * x * x + 5; C.assert(Math.abs(D2(y, 2)) < 1e-4 && Math.abs(D2(y, 1.9)) > 0.1, 'zero only at 2 nearby'); C.val(2); });

// =============================================================== short answer (2 marks)
Q('s201', mk.short({ marks: 2, stem: r`Show that $f(x) = \begin{cases} x^2 + 1, & x \le 1 \\ 3x - 1, & x > 1 \end{cases}$ is continuous at $x = 1$.`, model: r`$f(1) = 1 + 1 = 2$. Left-hand limit: $\lim_{x \to 1^-}(x^2 + 1) = 2$. Right-hand limit: $\lim_{x \to 1^+}(3x - 1) = 2$. Both limits equal $f(1) = 2$, so $f$ is continuous at $x = 1$.`, sol: 'Compare both one-sided limits with the value.', scheme: [['$f(1)$ and both one-sided limits found', 1], ['All equal $2$, so continuous', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => { const g = (x) => (x <= 1 ? x * x + 1 : 3 * x - 1); C.assert(isCont(g, 1, 2), 'continuous'); C.model([2, 'continuous']); });
Q('s202', mk.short({ marks: 2, stem: r`Examine the continuity of $f(x) = \begin{cases} 2x + 3, & x \le 2 \\ x + 4, & x > 2 \end{cases}$ at $x = 2$.`, model: r`$f(2) = 7$ and the left-hand limit is $7$. The right-hand limit is $\lim_{x \to 2^+}(x + 4) = 6$. Since $7 \ne 6$, the limit does not exist and $f$ is **not continuous** at $x = 2$ (a jump of $1$).`, sol: 'One-sided limits disagree.', scheme: [['Left limit $7$, right limit $6$', 1], ['Conclusion: not continuous', 1]], d: 2, c: 'understanding', t: [1], time: 90 }), (C) => { const g = (x) => (x <= 2 ? 2 * x + 3 : x + 4); C.assert(close(lim(g, 2, -1), 7) && close(lim(g, 2, 1), 6), '7 vs 6'); C.model([7, 6, 'not continuous']); });
Q('s203', mk.short({ marks: 2, stem: r`Differentiate $\cos\left(\sqrt{x}\right)$ with respect to $x$, for $x > 0$.`, model: r`Let $u = \sqrt{x}$, so $\dfrac{du}{dx} = \dfrac{1}{2\sqrt{x}}$. Then $\dfrac{d}{dx}\cos u = -\sin u \cdot \dfrac{du}{dx} = -\dfrac{\sin\sqrt{x}}{2\sqrt{x}}$.`, sol: 'Chain rule with the square root inside.', scheme: [['Derivative of the outer cosine', 1], ['Times $\\dfrac{1}{2\\sqrt{x}}$, final form', 1]], d: 2, c: 'understanding', t: [2], time: 90 }), (C) => { C.assert(sameD((x) => Co(sq(x)), (x) => -S(sq(x)) / (2 * sq(x)), [0.5, 2, 5]), 'derivative'); C.model([r`-\dfrac{\sin\sqrt{x}}{2\sqrt{x}}`]); });
Q('s204', mk.short({ marks: 2, stem: r`Find $\dfrac{dy}{dx}$ if $y = \sin^2(3x + 1)$.`, model: r`$\dfrac{dy}{dx} = 2\sin(3x + 1) \cdot \cos(3x + 1) \cdot 3 = 6\sin(3x + 1)\cos(3x + 1) = 3\sin(6x + 2)$.`, sol: 'Chain rule through the square, the sine and the linear inside.', scheme: [['Two chain-rule factors', 1], ['$3\\sin(6x + 2)$ or equivalent', 1]], d: 2, c: 'understanding', t: [2], time: 90 }), (C) => { C.assert(sameD((x) => S(3 * x + 1) ** 2, (x) => 3 * S(6 * x + 2), [0.1, 0.8, 1.7]), 'derivative'); C.model([r`3\sin(6x + 2)`]); });
Q('s205', mk.short({ marks: 2, stem: r`Find $\dfrac{dy}{dx}$ if $2x + 3y = \sin y$.`, model: r`Differentiate both sides with respect to $x$: $2 + 3\dfrac{dy}{dx} = \cos y\dfrac{dy}{dx}$. So $\dfrac{dy}{dx}(\cos y - 3) = 2$ and $\dfrac{dy}{dx} = \dfrac{2}{\cos y - 3}$.`, sol: 'Implicit differentiation; collect the derivative terms.', scheme: [['Differentiated correctly', 1], ['$\\dfrac{2}{\\cos y - 3}$', 1]], d: 2, c: 'understanding', t: [3], time: 90 }), (C) => { const F = (x, y) => 2 * x + 3 * y - S(y); const y0 = 0.5, x0 = (S(y0) - 3 * y0) / 2; C.assert(close(islope(F, x0, y0), 2 / (Co(y0) - 3)), 'implicit slope'); C.model([r`\dfrac{2}{\cos y - 3}`]); });
Q('s206', mk.short({ marks: 2, stem: r`Differentiate $\sin^{-1}(2x) + \cos^{-1}\left(\dfrac{x}{3}\right)$ with respect to $x$, for $-\dfrac12 < x < \dfrac12$.`, model: r`$\dfrac{d}{dx}\sin^{-1}(2x) = \dfrac{2}{\sqrt{1 - 4x^2}}$ and $\dfrac{d}{dx}\cos^{-1}\dfrac{x}{3} = -\dfrac{1}{\sqrt{1 - \frac{x^2}{9}}} \cdot \dfrac13 = -\dfrac{1}{\sqrt{9 - x^2}}$. Answer: $\dfrac{2}{\sqrt{1 - 4x^2}} - \dfrac{1}{\sqrt{9 - x^2}}$.`, sol: 'Use both inverse-function derivatives with the chain rule.', scheme: [['First term', 1], ['Second term with the minus sign', 1]], d: 3, c: 'application', t: [3], time: 120 }), (C) => { C.assert(sameD((x) => Math.asin(2 * x) + Math.acos(x / 3), (x) => 2 / sq(1 - 4 * x * x) - 1 / sq(9 - x * x), [-0.3, 0.1, 0.4]), 'derivative'); C.model([r`\dfrac{1}{\sqrt{9 - x^2}}`]); });
Q('s207', mk.short({ marks: 2, stem: r`Differentiate $e^x\log x$ with respect to $x$ ($x > 0$).`, model: r`Product rule: $\dfrac{d}{dx}(e^x\log x) = e^x\log x + e^x \cdot \dfrac{1}{x} = e^x\left(\log x + \dfrac{1}{x}\right)$.`, sol: 'Product rule.', scheme: [['Product rule set up', 1], ['$e^x\\left(\\log x + \\dfrac{1}{x}\\right)$', 1]], d: 2, c: 'understanding', t: [4], time: 75 }), (C) => { C.assert(sameD((x) => E(x) * L(x), (x) => E(x) * (L(x) + 1 / x), [0.5, 1, 3]), 'derivative'); C.model([r`\log x + \dfrac{1}{x}`]); });
Q('s208', mk.short({ marks: 2, stem: r`If $x = 4\cos t$ and $y = 3\sin t$, find $\dfrac{dy}{dx}$.`, model: r`$\dfrac{dx}{dt} = -4\sin t$ and $\dfrac{dy}{dt} = 3\cos t$. So $\dfrac{dy}{dx} = \dfrac{3\cos t}{-4\sin t} = -\dfrac{3}{4}\cot t$.`, sol: 'Divide the two parametric derivatives.', scheme: [['Both derivatives with respect to $t$', 1], ['$-\\dfrac{3}{4}\\cot t$', 1]], d: 2, c: 'understanding', t: [5], time: 90 }), (C) => { const t = 1.1; const y = (x) => 3 * sq(1 - (x * x) / 16); C.assert(close(D(y, 4 * Co(t)), (-3 / 4) / T(t)), 'eliminated slope'); C.model([r`-\dfrac{3}{4}\cot t`]); });
Q('s209', mk.short({ marks: 2, stem: r`If $y = 3e^{2x} + 2e^{-x}$, show that $\dfrac{d^2y}{dx^2} - \dfrac{dy}{dx} - 2y = 0$.`, model: r`$y' = 6e^{2x} - 2e^{-x}$ and $y'' = 12e^{2x} + 2e^{-x}$. Then $y'' - y' - 2y = (12 - 6 - 6)e^{2x} + (2 + 2 - 4)e^{-x} = 0$.`, sol: 'Differentiate twice and collect like exponentials.', scheme: [["$y'$ and $y''$", 1], ['Substitution gives $0$', 1]], d: 3, c: 'application', t: [5], time: 120 }), (C) => { const y = (x) => 3 * E(2 * x) + 2 * E(-x); C.assert([0, 0.4, 1].every((x) => Math.abs(D2(y, x) - D(y, x) - 2 * y(x)) < 1e-3), 'relation holds'); C.model([0]); });

// =============================================================== short answer (3 marks)
Q('s301', mk.short({ marks: 3, stem: r`Find $a$ and $b$ so that $f(x) = \begin{cases} 5, & x \le 1 \\ ax + b, & 1 < x < 4 \\ 17, & x \ge 4 \end{cases}$ is continuous at every real number.`, model: r`Each piece is a polynomial, so only $x = 1$ and $x = 4$ need checking. At $x = 1$: $a + b = 5$. At $x = 4$: $4a + b = 17$. Subtracting, $3a = 12$, so $a = 4$ and $b = 1$.`, sol: 'Equate one-sided limits at both break points.', scheme: [['$a + b = 5$', 1], ['$4a + b = 17$', 1], ['$a = 4$, $b = 1$', 1]], d: 3, c: 'application', t: [1], time: 150 }), (C) => { const [a, b] = solve2(1, 1, 5, 4, 1, 17); const g = (x) => (x <= 1 ? 5 : x < 4 ? a * x + b : 17); C.assert(isCont(g, 1, 5) && isCont(g, 4, 17), 'continuous at 1 and 4'); C.model([a, b]); });
Q('s302', mk.short({ marks: 3, stem: r`Show that $f(x) = x|x|$ is differentiable at $x = 0$ and find $f'(0)$.`, model: r`$f(0) = 0$. Right-hand derivative: $\lim_{h \to 0^+}\dfrac{h \cdot h - 0}{h} = \lim h = 0$. Left-hand derivative: $\lim_{h \to 0^-}\dfrac{h(-h) - 0}{h} = \lim(-h) = 0$. Both equal $0$, so $f$ is differentiable at $0$ and $f'(0) = 0$.`, sol: 'Use $|h| = h$ for $h > 0$ and $|h| = -h$ for $h < 0$.', scheme: [['Right-hand derivative $0$', 1], ['Left-hand derivative $0$', 1], ['Conclusion and $f\'(0) = 0$', 1]], d: 3, c: 'analysis', t: [2], time: 150 }), (C) => { const g = (x) => x * Math.abs(x); C.assert(Math.abs(LHD(g, 0)) < 1e-6 && Math.abs(RHD(g, 0)) < 1e-6, 'both 0'); C.model([0, 'differentiable']); });
Q('s303', mk.short({ marks: 3, stem: r`If $e^y + 2xy = e$, find $\dfrac{dy}{dx}$ and its value at the point $(0, 1)$.`, model: r`Check: $e^1 + 0 = e$, so $(0, 1)$ is on the curve. Differentiate: $e^y\dfrac{dy}{dx} + 2y + 2x\dfrac{dy}{dx} = 0$, so $\dfrac{dy}{dx} = -\dfrac{2y}{e^y + 2x}$. At $(0, 1)$: $\dfrac{dy}{dx} = -\dfrac{2}{e}$.`, sol: 'Implicit differentiation with the product rule on $2xy$.', scheme: [['Differentiation with product rule', 1], [r`$-\dfrac{2y}{e^y + 2x}$`, 1], [r`$-\dfrac{2}{e}$ at $(0, 1)$`, 1]], d: 3, c: 'application', t: [3, 4], time: 150 }), (C) => { const F = (x, y) => E(y) + 2 * x * y - Math.E; C.assert(Math.abs(F(0, 1)) < 1e-12 && close(islope(F, 0, 1), -2 / Math.E), 'slope -2/e'); C.model([r`-\dfrac{2}{e}`]); });
Q('s304', mk.short({ marks: 3, stem: r`Use logarithmic differentiation to find $\dfrac{dy}{dx}$ for $y = \dfrac{(x + 1)^2(2x - 1)^3}{(x + 4)^5}$, $x > \dfrac12$.`, model: r`$\log y = 2\log(x + 1) + 3\log(2x - 1) - 5\log(x + 4)$. Differentiate: $\dfrac{1}{y}\dfrac{dy}{dx} = \dfrac{2}{x + 1} + \dfrac{6}{2x - 1} - \dfrac{5}{x + 4}$. So $\dfrac{dy}{dx} = \dfrac{(x + 1)^2(2x - 1)^3}{(x + 4)^5}\left[\dfrac{2}{x + 1} + \dfrac{6}{2x - 1} - \dfrac{5}{x + 4}\right]$.`, sol: 'Take logs first; the chain rule on $\\log(2x - 1)$ gives the factor $2$.', scheme: [['Logs taken and expanded', 1], ['Differentiated (incl. factor $2$)', 1], ['Multiplied back by $y$', 1]], d: 3, c: 'application', t: [4], time: 180 }), (C) => { const y = (x) => ((x + 1) ** 2 * (2 * x - 1) ** 3) / (x + 4) ** 5; C.assert(sameD(y, (x) => y(x) * (2 / (x + 1) + 6 / (2 * x - 1) - 5 / (x + 4)), [1, 2, 3.5]), 'derivative'); C.model([r`\dfrac{6}{2x - 1}`]); });
Q('s305', mk.short({ marks: 3, stem: r`Find $\dfrac{dy}{dx}$ if $y = (\sin x)^x$, $0 < x < \pi$.`, model: r`$\log y = x\log(\sin x)$. Differentiate: $\dfrac{1}{y}\dfrac{dy}{dx} = \log(\sin x) + x \cdot \dfrac{\cos x}{\sin x}$. So $\dfrac{dy}{dx} = (\sin x)^x\left[\log(\sin x) + x\cot x\right]$.`, sol: 'Variable base and variable exponent: logarithmic differentiation.', scheme: [['Logs taken', 1], ['Product rule on the right', 1], ['Final answer', 1]], d: 3, c: 'application', t: [4], time: 150 }), (C) => { C.assert(sameD((x) => S(x) ** x, (x) => S(x) ** x * (L(S(x)) + x / T(x)), [0.5, 1, 2]), 'derivative'); C.model([r`x\cot x`]); });
Q('s306', mk.short({ marks: 3, stem: r`If $x = t + \dfrac{1}{t}$ and $y = t - \dfrac{1}{t}$ ($t > 1$), find $\dfrac{dy}{dx}$ and its value at $t = 2$.`, model: r`$\dfrac{dx}{dt} = 1 - \dfrac{1}{t^2}$ and $\dfrac{dy}{dt} = 1 + \dfrac{1}{t^2}$. So $\dfrac{dy}{dx} = \dfrac{t^2 + 1}{t^2 - 1}$. At $t = 2$: $\dfrac{5}{3}$.`, sol: 'Divide the derivatives; multiply top and bottom by $t^2$.', scheme: [['Both derivatives', 1], ['$\\dfrac{t^2 + 1}{t^2 - 1}$', 1], ['$\\dfrac{5}{3}$', 1]], d: 3, c: 'application', t: [5], time: 150 }), (C) => { const s = D((x) => sq(x * x - 4), 2.5); C.assert(close(s, 5 / 3), 'eliminated: x^2 - y^2 = 4'); C.model([r`\dfrac{5}{3}`]); });
Q('s307', mk.short({ marks: 3, stem: r`If $y = e^x\sin x$, show that $\dfrac{d^2y}{dx^2} - 2\dfrac{dy}{dx} + 2y = 0$.`, model: r`$y' = e^x\sin x + e^x\cos x = e^x(\sin x + \cos x)$. $y'' = e^x(\sin x + \cos x) + e^x(\cos x - \sin x) = 2e^x\cos x$. Then $y'' - 2y' + 2y = 2e^x\cos x - 2e^x\sin x - 2e^x\cos x + 2e^x\sin x = 0$.`, sol: 'Product rule twice, then substitute.', scheme: [["$y'$", 1], ["$y'' = 2e^x\\cos x$", 1], ['Substitution gives $0$', 1]], d: 3, c: 'application', t: [5], time: 150 }), (C) => { const y = (x) => E(x) * S(x); C.assert(sameD2(y, (x) => 2 * E(x) * Co(x), [0.2, 1, 1.8]) && [0.2, 1].every((x) => Math.abs(D2(y, x) - 2 * D(y, x) + 2 * y(x)) < 1e-3), 'relation'); C.model([r`2e^x\cos x`]); });
Q('s308', mk.short({ marks: 3, stem: r`Differentiate $\sqrt{\sin(x^2 + 1)}$ with respect to $x$, where $\sin(x^2 + 1) > 0$.`, model: r`Three layers: square root, sine, $x^2 + 1$. $\dfrac{dy}{dx} = \dfrac{1}{2\sqrt{\sin(x^2 + 1)}} \cdot \cos(x^2 + 1) \cdot 2x = \dfrac{x\cos(x^2 + 1)}{\sqrt{\sin(x^2 + 1)}}$.`, sol: 'Chain rule applied twice.', scheme: [['Derivative of the square root', 1], ['Derivative of the sine and of $x^2 + 1$', 1], ['Simplified answer', 1]], d: 3, c: 'understanding', t: [2], time: 150 }), (C) => { C.assert(sameD((x) => sq(S(x * x + 1)), (x) => (x * Co(x * x + 1)) / sq(S(x * x + 1)), [0.2, 0.5, 1]), 'derivative'); C.model([r`\dfrac{x\cos(x^2 + 1)}{\sqrt{\sin(x^2 + 1)}}`]); });

// =============================================================== long answer (5 marks)
Q('l01', mk.long({ stem: r`Let $f(x) = \begin{cases} ax + 3, & x < 2 \\ 7, & x = 2 \\ bx^2 - 1, & x > 2 \end{cases}$.
(a) Find $a$ and $b$ so that $f$ is continuous at $x = 2$.
(b) For these values, check whether $f$ is differentiable at $x = 2$.`, model: r`(a) $f(2) = 7$. Left-hand limit $2a + 3 = 7$ gives $a = 2$. Right-hand limit $4b - 1 = 7$ gives $b = 2$.
(b) With $a = 2$, $b = 2$: for $x < 2$, $f(x) = 2x + 3$, so the left-hand derivative is $\lim_{h \to 0^-}\dfrac{2(2 + h) + 3 - 7}{h} = 2$. For $x > 2$, $f(x) = 2x^2 - 1$, so the right-hand derivative is $\lim_{h \to 0^+}\dfrac{2(2 + h)^2 - 1 - 7}{h} = \lim(8 + 2h) = 8$. Since $2 \ne 8$, $f$ is continuous but **not differentiable** at $x = 2$.`, sol: 'Continuity fixes the constants; the one-sided derivatives decide differentiability.', scheme: [['$a = 2$', 1], ['$b = 2$', 1], ['Left-hand derivative $2$', 1], ['Right-hand derivative $8$', 1], ['Conclusion: not differentiable', 1]], d: 3, c: 'application', t: [1, 2], time: 360 }), (C) => { const a = (7 - 3) / 2, b = (7 + 1) / 4; const g = (x) => (x < 2 ? a * x + 3 : x === 2 ? 7 : b * x * x - 1); C.assert(isCont(g, 2, 7), 'continuous'); C.assert(close(LHD(g, 2), 2, 1e-4) && close(RHD(g, 2), 8, 1e-4), 'LHD 2, RHD 8'); C.model([a, b, 2, 8, 'not differentiable']); });
Q('l02', mk.long({ stem: r`If $y = e^{2\sin^{-1} x}$, $-1 < x < 1$, show that $(1 - x^2)\dfrac{d^2y}{dx^2} - x\dfrac{dy}{dx} - 4y = 0$.`, model: r`$\dfrac{dy}{dx} = e^{2\sin^{-1} x} \cdot \dfrac{2}{\sqrt{1 - x^2}} = \dfrac{2y}{\sqrt{1 - x^2}}$, so $\sqrt{1 - x^2}\,\dfrac{dy}{dx} = 2y$.
Differentiate again (product rule): $\sqrt{1 - x^2}\,\dfrac{d^2y}{dx^2} - \dfrac{x}{\sqrt{1 - x^2}}\dfrac{dy}{dx} = 2\dfrac{dy}{dx}$.
Multiply by $\sqrt{1 - x^2}$: $(1 - x^2)\dfrac{d^2y}{dx^2} - x\dfrac{dy}{dx} = 2\sqrt{1 - x^2}\,\dfrac{dy}{dx} = 2 \cdot 2y = 4y$.
Hence $(1 - x^2)\dfrac{d^2y}{dx^2} - x\dfrac{dy}{dx} - 4y = 0$.`, sol: 'Clear the root before differentiating again.', scheme: [['First derivative', 1], ['Rearranged to $\\sqrt{1 - x^2}\\,y\' = 2y$', 1], ['Second differentiation', 1], ['Multiply by $\\sqrt{1 - x^2}$', 1], ['Use the first result to reach $4y$', 1]], d: 4, c: 'analysis', t: [3, 5], time: 420 }), (C) => { const y = (x) => E(2 * Math.asin(x)); C.assert([-0.4, 0.1, 0.5].every((x) => Math.abs((1 - x * x) * D2(y, x) - x * D(y, x) - 4 * y(x)) < 1e-3), 'relation'); C.model([4]); });
Q('l03', mk.long({ stem: r`Find $\dfrac{dy}{dx}$ if $y = x^{3x} + (\cos x)^x$, $0 < x < \dfrac{\pi}{2}$.`, model: r`Let $u = x^{3x}$ and $v = (\cos x)^x$, so $\dfrac{dy}{dx} = \dfrac{du}{dx} + \dfrac{dv}{dx}$.
$\log u = 3x\log x$, so $\dfrac{1}{u}\dfrac{du}{dx} = 3\log x + 3$ and $\dfrac{du}{dx} = 3x^{3x}(1 + \log x)$.
$\log v = x\log(\cos x)$, so $\dfrac{1}{v}\dfrac{dv}{dx} = \log(\cos x) - x\tan x$ and $\dfrac{dv}{dx} = (\cos x)^x\left[\log(\cos x) - x\tan x\right]$.
Hence $\dfrac{dy}{dx} = 3x^{3x}(1 + \log x) + (\cos x)^x\left[\log(\cos x) - x\tan x\right]$.`, sol: 'Split the sum first; take logs of each part separately, never of the sum.', scheme: [['Split into $u + v$', 1], ['$\\log u$ differentiated', 1], ['$u\'$', 1], ['$\\log v$ differentiated', 1], ['$v\'$ and final sum', 1]], d: 4, c: 'application', t: [4], time: 420 }), (C) => { const y = (x) => x ** (3 * x) + Co(x) ** x; C.assert(sameD(y, (x) => 3 * x ** (3 * x) * (1 + L(x)) + Co(x) ** x * (L(Co(x)) - x * T(x)), [0.3, 0.7, 1.2]), 'derivative'); C.model([r`3x^{3x}(1 + \log x)`, r`\log(\cos x) - x\tan x`]); });
Q('l04', mk.long({ stem: r`A curve is given by $x = 3t - t^3$, $y = 3t^2$, for $-1 < t < 1$.
(a) Find $\dfrac{dy}{dx}$ in terms of $t$.
(b) Find $\dfrac{d^2y}{dx^2}$ in terms of $t$, and its value at $t = \dfrac12$.`, model: r`(a) $\dfrac{dx}{dt} = 3 - 3t^2$, $\dfrac{dy}{dt} = 6t$, so $\dfrac{dy}{dx} = \dfrac{6t}{3(1 - t^2)} = \dfrac{2t}{1 - t^2}$.
(b) $\dfrac{d}{dt}\left(\dfrac{2t}{1 - t^2}\right) = \dfrac{2(1 - t^2) + 4t^2}{(1 - t^2)^2} = \dfrac{2(1 + t^2)}{(1 - t^2)^2}$. Divide by $\dfrac{dx}{dt} = 3(1 - t^2)$: $\dfrac{d^2y}{dx^2} = \dfrac{2(1 + t^2)}{3(1 - t^2)^3}$.
At $t = \dfrac12$: $\dfrac{2 \cdot \frac54}{3 \cdot \frac{27}{64}} = \dfrac{160}{81}$. (Also $\dfrac{dy}{dx} = \dfrac{4}{3}$ there.)`, sol: 'For the second derivative, differentiate the first derivative with respect to $t$ and divide by $\\dfrac{dx}{dt}$ again.', scheme: [['Parametric derivatives', 1], ['$\\dfrac{2t}{1 - t^2}$', 1], ['Derivative of that with respect to $t$', 1], ['Divided by $\\dfrac{dx}{dt}$', 1], ['$\\dfrac{160}{81}$', 1]], d: 5, c: 'analysis', t: [5], time: 480 }), (C) => {
  const tOf = (x) => { let t = 0; for (let i = 0; i < 60; i++) t -= (3 * t - t ** 3 - x) / (3 - 3 * t * t); return t; };
  const y = (x) => 3 * tOf(x) ** 2; const x0 = 3 * 0.5 - 0.125;
  C.assert(close(D(y, x0), 4 / 3) && close(D2(y, x0), 160 / 81, 1e-3), 'slope 4/3, second derivative 160/81'); C.model([r`\dfrac{160}{81}`, r`\dfrac{4}{3}`]);
});
Q('l05', mk.long({ stem: r`The curve $x^2 + 2xy + 3y^2 = 6$ passes through $P(1, 1)$.
(a) Find $\dfrac{dy}{dx}$ at $P$.
(b) Find $\dfrac{d^2y}{dx^2}$ at $P$.`, model: r`Check: $1 + 2 + 3 = 6$. (a) Differentiate: $2x + 2y + 2x\dfrac{dy}{dx} + 6y\dfrac{dy}{dx} = 0$, so $\dfrac{dy}{dx} = -\dfrac{x + y}{x + 3y}$. At $P$: $-\dfrac{2}{4} = -\dfrac12$.
(b) Write $y' = \dfrac{dy}{dx}$. By the quotient rule, $\dfrac{d^2y}{dx^2} = -\dfrac{(1 + y')(x + 3y) - (x + y)(1 + 3y')}{(x + 3y)^2}$.
At $P$ with $y' = -\dfrac12$: numerator $= \dfrac12 \cdot 4 - 2\left(-\dfrac12\right) = 2 + 1 = 3$; denominator $16$.
So $\dfrac{d^2y}{dx^2} = -\dfrac{3}{16}$ at $P$.`, sol: 'Differentiate the first-derivative expression as a quotient, treating $y$ as a function of $x$; substitute only at the end.', scheme: [['Implicit differentiation', 1], ['$-\\dfrac12$ at $P$', 1], ['Quotient rule set up', 1], ['Substitution of $y\'$', 1], ['$-\\dfrac{3}{16}$', 1]], d: 4, c: 'analysis', t: [3, 5], time: 420 }), (C) => { const y = (x) => (-2 * x + sq(72 - 8 * x * x)) / 6; C.assert(close(y(1), 1), 'P on branch'); C.assert(close(D(y, 1), -0.5) && close(D2(y, 1), -3 / 16, 1e-3), 'slope -1/2, second -3/16'); C.model([3 / 16]); });
Q('l06', mk.long({ stem: r`Differentiate with respect to $x$:
(a) $\log\left(x + \sqrt{x^2 + 4}\right)$;
(b) $\dfrac{e^{2x}}{1 + \log x}$, for $x > 1$.`, model: r`(a) $\dfrac{1}{x + \sqrt{x^2 + 4}}\left(1 + \dfrac{x}{\sqrt{x^2 + 4}}\right) = \dfrac{1}{x + \sqrt{x^2 + 4}} \cdot \dfrac{\sqrt{x^2 + 4} + x}{\sqrt{x^2 + 4}} = \dfrac{1}{\sqrt{x^2 + 4}}$.
(b) Quotient rule: $\dfrac{(1 + \log x) \cdot 2e^{2x} - e^{2x} \cdot \frac{1}{x}}{(1 + \log x)^2} = \dfrac{e^{2x}\left[2(1 + \log x) - \frac{1}{x}\right]}{(1 + \log x)^2}$.`, sol: 'In (a) the bracket cancels with the outer reciprocal; in (b) apply the quotient rule.', scheme: [['(a) chain rule', 1], ['(a) simplified to $\\dfrac{1}{\\sqrt{x^2 + 4}}$', 1], ['(b) quotient rule set up', 1], ['(b) derivatives of numerator and denominator', 1], ['(b) final form', 1]], d: 3, c: 'application', t: [2, 4], time: 360 }), (C) => { C.assert(sameD((x) => L(x + sq(x * x + 4)), (x) => 1 / sq(x * x + 4), [-1, 0.5, 3]), '(a)'); C.assert(sameD((x) => E(2 * x) / (1 + L(x)), (x) => (E(2 * x) * (2 * (1 + L(x)) - 1 / x)) / (1 + L(x)) ** 2, [1.5, 2, 3]), '(b)'); C.model([r`\dfrac{1}{\sqrt{x^2 + 4}}`]); });

// =============================================================== case-based
caseQ('c01', {
  passage: r`A courier service in Coimbatore charges for parcels by weight $w$ (in kg). For $0 < w \le 5$ the charge is $C(w) = 60 + 20w$ rupees. For $w > 5$ the charge is $C(w) = 110 + kw$ rupees, where $k$ is a constant chosen so that customers see no sudden jump in price at $5$ kg.`,
  d: 3, c: 'application',
  model: r`(a) Option (c): ₹$120$. (b) $10$. (c) (i) Left-hand limit and $C(5)$ are $160$; right-hand limit $110 + 50 = 160$; equal, so continuous. Or (ii) Right-hand limit $170 \ne 160$: not continuous; the jump is ₹$10$.`,
  sol: r`(a) $60 + 20 \times 3$. (b) $60 + 100 = 110 + 5k$. (c) Compare the one-sided limits at $w = 5$.`,
  children: [
    child('a', mk.mcq({ stem: 'The charge for a 3 kg parcel is', opts: ['₹$80$', '₹$100$', '₹$120$', '₹$140$'], key: 'c', sol: r`$C(3) = 60 + 20 \times 3 = 120$.`, d: 1, c: 'understanding', t: [1], time: 30 })),
    child('b', mk.num({ stem: r`Find $k$.`, value: 10, sol: r`No jump at $5$: $60 + 20 \times 5 = 160 = 110 + 5k$, so $k = 10$.`, scheme: [['10', 1]], d: 2, c: 'application', t: [1], time: 60 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** With this $k$, show that $C$ is continuous at $w = 5$.`, model: r`$C(5) = 160$ and the left-hand limit is $\lim_{w \to 5^-}(60 + 20w) = 160$. Right-hand limit: $\lim_{w \to 5^+}(110 + 10w) = 160$. All three are equal, so $C$ is continuous at $w = 5$.`, sol: 'Both one-sided limits against the value.', scheme: [['Both limits $160$', 1], ['Conclusion', 1]], d: 2, c: 'understanding', t: [1], time: 120 }), [
      mk.short({ marks: 2, stem: r`**(ii)** Suppose the rule for $w > 5$ were $C(w) = 120 + 10w$ instead. Is $C$ continuous at $w = 5$? Find the size of any jump.`, model: r`Left-hand limit and $C(5)$: $160$. Right-hand limit: $120 + 50 = 170$. Since $170 \ne 160$, $C$ is not continuous at $w = 5$; the price jumps by ₹$10$.`, sol: 'Compare the two one-sided limits.', scheme: [['Right-hand limit $170$', 1], ['Not continuous; jump ₹$10$', 1]], d: 3, c: 'application', t: [1], time: 120 }),
    ]),
  ],
}, (C) => { const k = (60 + 20 * 5 - 110) / 5; const g = (w) => (w <= 5 ? 60 + 20 * w : 110 + k * w); C.child('a').which([80, 100, 120, 140], g(3)); C.child('b').val(k); C.child('c').assert(isCont(g, 5, 160), 'continuous'); C.child('c').model([160]); const g2 = (w) => (w <= 5 ? 60 + 20 * w : 120 + 10 * w); const rl = Math.round(lim(g2, 5, 1)); C.child('cii').assert(rl === 170 && !isCont(g2, 5, 160), 'jump'); C.child('cii').model([rl, rl - g2(5)]); });

caseQ('c02', {
  passage: r`An approach road to a flyover in Bengaluru is designed so that its height $h$ (in metres) above the ground, at a horizontal distance $x$ m from the start, is $h(x) = \dfrac{x^2}{40}$ for $0 \le x \le 20$ and $h(x) = x - 10$ for $20 < x \le 50$. Engineers want no step (continuity) and no sharp bend (differentiability) where the two parts meet.`,
  d: 3, c: 'application',
  model: r`(a) Option (b): $10$ m. (b) $0.5$. (c) (i) Left-hand derivative $\dfrac{2 \times 20}{40} = 1$, right-hand derivative $1$; equal, so differentiable at $x = 20$ (no sharp bend). Or (ii) Continuous ($1.5 \times 20 - 20 = 10$) but the slopes $1$ and $1.5$ differ, so not differentiable: a sharp bend.`,
  sol: r`(a) $h(20) = 400 \div 40$. (b) $h'(x) = \dfrac{x}{20}$ on the first part. (c) Compare one-sided derivatives at $20$.`,
  children: [
    child('a', mk.mcq({ stem: r`The height of the road at $x = 20$ m is`, opts: ['$20$ m', '$10$ m', '$40$ m', '$5$ m'], key: 'b', sol: r`$h(20) = \dfrac{400}{40} = 10$, and the second part also gives $20 - 10 = 10$.`, d: 1, c: 'understanding', t: [1], time: 45 })),
    child('b', mk.num({ stem: r`Find the slope $h'(x)$ of the road at $x = 10$ m.`, value: 0.5, sol: r`$h'(x) = \dfrac{2x}{40} = \dfrac{x}{20}$, so $h'(10) = 0.5$.`, scheme: [['0.5', 1]], d: 2, c: 'understanding', t: [2], time: 60 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** Show that $h$ is differentiable at $x = 20$.`, model: r`$h$ is continuous at $20$ (both parts give $10$). Left-hand derivative: $\dfrac{2 \times 20}{40} = 1$. Right-hand derivative: derivative of $x - 10$ is $1$. They are equal, so $h$ is differentiable at $x = 20$ and $h'(20) = 1$.`, sol: 'One-sided derivatives at the joint.', scheme: [['Both one-sided derivatives equal $1$', 1], ['Conclusion', 1]], d: 3, c: 'application', t: [2], time: 120 }), [
      mk.short({ marks: 2, stem: r`**(ii)** If the second part were $h(x) = 1.5x - 20$ instead, would the road still be continuous and differentiable at $x = 20$? Justify.`, model: r`At $x = 20$ the new part gives $1.5 \times 20 - 20 = 10$, the same height, so $h$ is still continuous. But the left-hand derivative is $1$ and the right-hand derivative is $1.5$; they differ, so $h$ is not differentiable at $x = 20$: the road has a sharp bend.`, sol: 'Heights match, slopes do not.', scheme: [['Continuous: both $10$', 1], ['Slopes $1$ and $1.5$: not differentiable', 1]], d: 3, c: 'analysis', t: [1, 2], time: 120 }),
    ]),
  ],
}, (C) => { const h = (x) => (x <= 20 ? (x * x) / 40 : x - 10); C.child('a').which([20, 10, 40, 5], h(20)); C.child('b').val(D(h, 10), 1e-6); C.child('c').assert(isCont(h, 20, 10) && close(LHD(h, 20), 1, 1e-4) && close(RHD(h, 20), 1, 1e-4), 'differentiable'); C.child('c').model([1]); const h2 = (x) => (x <= 20 ? (x * x) / 40 : 1.5 * x - 20); C.child('cii').assert(isCont(h2, 20, 10) && close(RHD(h2, 20), 1.5, 1e-4), 'corner'); C.child('cii').model([10, 1.5]); });

caseQ('c03', {
  passage: r`In a biotechnology lab in Hyderabad, the number of bacteria in a culture $t$ hours after the start is modelled by $N(t) = 500e^{0.4t}$.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $500$. (b) $200$. (c) (i) $\dfrac{dN}{dt} = 500 \times 0.4e^{0.4t} = 0.4N$: the growth rate is proportional to the population. Or (ii) $\log N = \log 500 + 0.4t$, so $\dfrac{d}{dt}(\log N) = 0.4$, a constant.`,
  sol: r`(a) $e^0 = 1$. (b) $\dfrac{dN}{dt} = 200e^{0.4t}$. (c) Differentiate the exponential or take logs.`,
  children: [
    child('a', mk.mcq({ stem: 'The number of bacteria at the start is', opts: ['$500$', '$200$', '$0.4$', '$900$'], key: 'a', sol: r`$N(0) = 500e^0 = 500$.`, d: 1, c: 'recall', t: [4], time: 30 })),
    child('b', mk.num({ stem: r`Find $\dfrac{dN}{dt}$ at $t = 0$ (bacteria per hour).`, value: 200, sol: r`$\dfrac{dN}{dt} = 500 \times 0.4e^{0.4t} = 200e^{0.4t}$; at $t = 0$, $\dfrac{dN}{dt} = 200e^{0} = 200$.`, scheme: [['200', 1]], d: 2, c: 'understanding', t: [4], time: 60 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** Show that $\dfrac{dN}{dt} = 0.4N$ and interpret it.`, model: r`$\dfrac{dN}{dt} = 500 \times 0.4e^{0.4t} = 0.4 \times 500e^{0.4t} = 0.4N$. The culture grows at a rate proportional to its size: more bacteria, faster growth.`, sol: 'Differentiate and compare with N.', scheme: [['Derivative', 1], ['$0.4N$ with interpretation', 1]], d: 2, c: 'application', t: [4], time: 120 }), [
      mk.short({ marks: 2, stem: r`**(ii)** Show that $\dfrac{d}{dt}\left(\log N\right)$ is a constant and find it.`, model: r`$\log N = \log 500 + 0.4t$, since $\log e^{0.4t} = 0.4t$. Differentiating, $\dfrac{d}{dt}(\log N) = 0 + 0.4 = 0.4$, a constant.`, sol: 'Take logs first.', scheme: [['$\\log N = \\log 500 + 0.4t$', 1], ['Derivative $0.4$', 1]], d: 3, c: 'application', t: [4], time: 120 }),
    ]),
  ],
}, (C) => { const N = (t) => 500 * E(0.4 * t); C.child('a').which([500, 200, 0.4, 900], N(0)); C.child('b').val(D(N, 0), 1e-4); C.child('c').assert([0, 2, 5].every((t) => close(D(N, t), 0.4 * N(t))), 'dN/dt = 0.4N'); C.child('c').model([0.4]); C.child('cii').assert(close(D((t) => L(N(t)), 3), 0.4), 'd log N = 0.4'); C.child('cii').model([0.4]); });

caseQ('c04', {
  passage: r`At the kite festival in Jaipur, a small hot-air balloon is released from a rooftop. Taking the launch point as origin, its position after $t$ seconds is $x = 6t$ metres across and $y = 24t - 3t^2$ metres up, for $0 \le t \le 8$.`,
  d: 3, c: 'application',
  model: r`(a) Option (d): $4 - t$. (b) $4$. (c) (i) $\dfrac{d^2y}{dx^2} = -\dfrac{1}{6}$. Or (ii) $48$ m.`,
  sol: r`(a) $\dfrac{dy}{dx} = \dfrac{24 - 6t}{6}$. (b) Set $4 - t = 0$. (c) Differentiate $4 - t$ with respect to $t$ and divide by $\dfrac{dx}{dt}$; or find $y(4)$.`,
  children: [
    child('a', mk.mcq({ stem: r`The slope $\dfrac{dy}{dx}$ of the balloon's path at time $t$ is`, opts: ['$24 - 6t$', '$6$', r`$\dfrac{6}{24 - 6t}$`, '$4 - t$'], key: 'd', sol: r`$\dfrac{dy}{dt} = 24 - 6t$ and $\dfrac{dx}{dt} = 6$, so $\dfrac{dy}{dx} = 4 - t$. The first option is $\dfrac{dy}{dt}$, not the slope.`, d: 2, c: 'understanding', t: [5], time: 60 })),
    child('b', mk.num({ stem: r`At what time $t$ (in seconds) is the path momentarily level, that is $\dfrac{dy}{dx} = 0$?`, value: 4, unit: 's', sol: r`$4 - t = 0$ gives $t = 4$.`, scheme: [['4', 1]], d: 2, c: 'understanding', t: [5], time: 45 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** Find $\dfrac{d^2y}{dx^2}$ and say what its sign tells you about the path.`, model: r`$\dfrac{d^2y}{dx^2} = \dfrac{\frac{d}{dt}(4 - t)}{\frac{dx}{dt}} = \dfrac{-1}{6} = -\dfrac{1}{6}$. It is negative and constant, so the slope keeps decreasing: the path bends downward everywhere.`, sol: 'Second derivative of a parametric curve: divide by dx/dt again.', scheme: [['$-\\dfrac{1}{6}$', 1], ['Interpretation of the sign', 1]], d: 3, c: 'application', t: [5], time: 120 }), [
      mk.short({ marks: 2, stem: r`**(ii)** Find the height and horizontal distance of the balloon when the path is level.`, model: r`The path is level at $t = 4$ (slope $4 - t = 0$). Then $x = 6 \times 4 = 24$ m and $y = 24 \times 4 - 3 \times 16 = 96 - 48 = 48$ m.`, sol: 'Substitute the time found from the slope.', scheme: [['$t = 4$', 1], ['$x = 24$ m, $y = 48$ m', 1]], d: 2, c: 'application', t: [5], time: 90 }),
    ]),
  ],
}, (C) => { const y = (x) => 4 * x - (x * x) / 12; const t = 2.5; C.child('a').which([24 - 6 * t, 6, 6 / (24 - 6 * t), 4 - t].map((v) => close(v, D(y, 6 * t))), true); const tl = 24 / 6; C.child('b').val(tl); C.child('c').assert(close(D2(y, 10), -1 / 6, 1e-4), 'y\'\' = -1/6'); C.child('c').model([r`-\dfrac{1}{6}`]); C.child('cii').assert(Math.abs(D(y, 6 * tl)) < 1e-6, 'level'); C.child('cii').model([6 * tl, 24 * tl - 3 * tl * tl]); });

caseQ('c05', {
  passage: r`A circular jogging track in a Mysuru park is modelled by $x^2 + y^2 = 100$, with distances in metres and the centre of the park at the origin. A jogger is at the point $J(6, 8)$.`,
  d: 3, c: 'application',
  model: r`(a) Option (a): $-\dfrac{x}{y}$. (b) $-0.75$. (c) (i) $\dfrac{d^2y}{dx^2} = -\dfrac{x^2 + y^2}{y^3} = -\dfrac{100}{512} = -\dfrac{25}{128}$. Or (ii) $(0, 10)$ and $(0, -10)$.`,
  sol: r`(a) Implicit differentiation. (b) $-\dfrac{6}{8}$. (c) Differentiate $-\dfrac{x}{y}$ again, or set $x = 0$.`,
  children: [
    child('a', mk.mcq({ stem: r`For the track, $\dfrac{dy}{dx}$ equals`, opts: [r`$-\dfrac{x}{y}$`, r`$\dfrac{x}{y}$`, r`$-\dfrac{y}{x}$`, '$-2x$'], key: 'a', sol: r`$2x + 2y\dfrac{dy}{dx} = 0$ gives $\dfrac{dy}{dx} = -\dfrac{x}{y}$.`, d: 2, c: 'understanding', t: [3], time: 45 })),
    child('b', mk.num({ stem: r`Find $\dfrac{dy}{dx}$ at $J(6, 8)$.`, value: -0.75, sol: r`$-\dfrac{x}{y} = -\dfrac{6}{8} = -0.75$.`, scheme: [['-0.75', 1]], d: 2, c: 'understanding', t: [3], time: 45 })),
    child('c', mk.short({ marks: 2, stem: r`**(i)** Find $\dfrac{d^2y}{dx^2}$ at $J$.`, model: r`$\dfrac{d^2y}{dx^2} = -\dfrac{y - x\frac{dy}{dx}}{y^2} = -\dfrac{y^2 + x^2}{y^3}$, using $\dfrac{dy}{dx} = -\dfrac{x}{y}$. At $J$: $-\dfrac{100}{512} = -\dfrac{25}{128}$.`, sol: 'Quotient rule on -x/y, then substitute the first derivative.', scheme: [['$-\\dfrac{x^2 + y^2}{y^3}$', 1], ['$-\\dfrac{25}{128}$', 1]], d: 4, c: 'application', t: [3, 5], time: 150 }), [
      mk.short({ marks: 2, stem: r`**(ii)** At which points of the track is $\dfrac{dy}{dx} = 0$? Describe the jogger's direction there.`, model: r`$-\dfrac{x}{y} = 0$ needs $x = 0$; then $y^2 = 100$, so $y = 10$ or $y = -10$. At $(0, 10)$ and $(0, -10)$ the jogger is moving parallel to the $x$-axis (due east or west).`, sol: 'Set the numerator to zero and use the equation of the track.', scheme: [['$x = 0$', 1], ['$(0, 10)$ and $(0, -10)$', 1]], d: 2, c: 'application', t: [3], time: 90 }),
    ]),
  ],
}, (C) => { const y = (x) => sq(100 - x * x); C.child('a').which([-6 / 8, 6 / 8, -8 / 6, -12].map((v) => close(v, D(y, 6))), true); C.child('b').val(D(y, 6), 1e-6); C.child('c').assert(close(D2(y, 6), -25 / 128, 1e-4), 'second derivative'); C.child('c').model([r`-\dfrac{25}{128}`]); C.child('cii').assert(Math.abs(D(y, 0)) < 1e-9 && y(0) === 10, 'level at (0, 10)'); C.child('cii').model([10]); });

// =============================================================== added items (application)
Q('a01', mk.short({ marks: 3, stem: r`A function is defined on both sides of the origin by different formulas. Using standard limits, determine the constant $k$ for which $f(x) = \begin{cases} \dfrac{\sin 5x}{3x}, & x < 0 \\ k, & x = 0 \\ \dfrac{e^{5x} - 1}{3x}, & x > 0 \end{cases}$ is continuous at $x = 0$.`, model: r`Left-hand limit: $\dfrac{\sin 5x}{3x} = \dfrac{5}{3} \cdot \dfrac{\sin 5x}{5x} \to \dfrac{5}{3} \cdot 1 = \dfrac{5}{3}$. Right-hand limit: $\dfrac{e^{5x} - 1}{3x} = \dfrac{5}{3} \cdot \dfrac{e^{5x} - 1}{5x} \to \dfrac{5}{3} \cdot 1 = \dfrac{5}{3}$. The limits agree, so $f$ is continuous at $0$ exactly when $k = \dfrac{5}{3}$.`, sol: 'Use the standard limits of sin u over u and (e^u minus 1) over u as u tends to 0.', scheme: [[r`Left-hand limit $\dfrac{5}{3}$`, 1], [r`Right-hand limit $\dfrac{5}{3}$`, 1], [r`$k = \dfrac{5}{3}$`, 1]], d: 3, c: 'application', t: [1], time: 150 }), (C) => { const g = (x) => (x < 0 ? S(5 * x) / (3 * x) : (E(5 * x) - 1) / (3 * x)); C.assert(Math.abs(g(-1e-6) - 5 / 3) < 1e-4 && Math.abs(g(1e-6) - 5 / 3) < 1e-4, 'both limits 5/3'); C.model([r`k = \dfrac{5}{3}`]); });
Q('a02', mk.num({ stem: r`A fixed deposit in a Pune bank grows so that its value after $t$ years is $V(t) = 2000(1.1)^t$ rupees. Find the rate of growth $\dfrac{dV}{dt}$ at $t = 0$, in rupees per year, correct to two decimal places.`, value: 190.62, tol: 0.01, unit: '₹ per year', sol: r`$\dfrac{d}{dt}a^t = a^t\log a$, so $\dfrac{dV}{dt} = 2000(1.1)^t\log 1.1$. At $t = 0$: $2000\log 1.1 \approx 2000 \times 0.09531 = 190.62$.`, scheme: [[r`$2000\log 1.1$, then $190.62$`, 1]], d: 3, c: 'application', t: [4], time: 120 }), (C) => C.val(D((t) => 2000 * 1.1 ** t, 0), 0.01));
Q('a03', mk.short({ marks: 2, stem: r`If $y = \tan^{-1} x$, show that $(1 + x^2)\dfrac{d^2y}{dx^2} + 2x\dfrac{dy}{dx} = 0$.`, model: r`$\dfrac{dy}{dx} = \dfrac{1}{1 + x^2}$, so $(1 + x^2)\dfrac{dy}{dx} = 1$. Differentiate both sides with the product rule: $2x\dfrac{dy}{dx} + (1 + x^2)\dfrac{d^2y}{dx^2} = 0$, which is the required relation.`, sol: 'Clear the fraction first, then differentiate again.', scheme: [['$(1 + x^2)y\' = 1$', 1], ['Product rule gives the relation', 1]], d: 3, c: 'application', t: [3, 5], time: 120 }), (C) => { C.assert([-1, 0.3, 2].every((x) => Math.abs((1 + x * x) * D2(Math.atan, x) + 2 * x * D(Math.atan, x)) < 1e-4), 'relation'); C.model([0]); });
